package com.lianxibu.site.config;
import com.lianxibu.site.domain.protocol.WireValues;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.repository.settings.JdbcSettingsWrites;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.SmartLifecycle;import org.springframework.context.annotation.*;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** One JVM native API stream, original current settings and a separate permanent sampler. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name={"site.ops.api-monitoring.enabled","site.browser.enabled"},havingValue="true")
public class ApiMonitoringConfiguration {
 public record Batch(List<ApiMonitoringCycle> cycles,ProcessApiRuntimeTelemetry nativeFacts){public Batch{cycles=List.copyOf(cycles);if(cycles.isEmpty()||nativeFacts==null)throw new IllegalArgumentException("native API monitor required");}@Override public String toString(){return "ApiMonitoringBatch[redacted]";}}
 @Bean Batch apiMonitoringBatch(DataSource source,PlatformTransactionManager tx,ApiRuntimeInstrumentationConfiguration.NativeCapture capture,@Value("${SITE_API_MONITOR_RESOURCE}")String resource){if(capture.probe!=ProcessApiRuntimeTelemetry.nativeProcess())throw new IllegalStateException("native API capture unavailable");return create(source,tx,capture.probe,new OperationalRuleEngine.Key("OPS-09","java",WireValues.id(resource,false)),Clock.systemUTC());}
 public static Batch create(DataSource source,PlatformTransactionManager tx,ProcessApiRuntimeTelemetry facts,OperationalRuleEngine.Key key,Clock clock){
  Objects.requireNonNull(source);Objects.requireNonNull(tx);Objects.requireNonNull(facts);Objects.requireNonNull(clock);if(key==null||!"OPS-09".equals(key.ruleId())||!"java".equals(key.component()))throw new IllegalArgumentException("native API operational binding unavailable");WireValues.id(key.resourceKey(),false);
  var settings=new SettingsJdbcStore(new JdbcSettingsWrites(source),ignored->false,change->{throw new IllegalStateException("read-only API monitoring settings");},clock);
  java.util.function.Supplier<OperationalMonitoringService.Configuration> current=()->{var config=settings.operationalConfiguration();return config.ready()?new OperationalMonitoringService.Configuration(config.revision(),config.rules()):null;};
  OperationalMonitoringService.ConfigurationSource configuration=()->{if(TransactionSynchronizationManager.isActualTransactionActive())return current.get();var reader=new TransactionTemplate(tx);reader.setReadOnly(true);reader.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reader.setTimeout(10);return reader.execute(status->current.get());};
  var store=new OperationalJdbcStore(new JdbcOperationalSummaries(source),new JdbcJobRecords(source),clock);var monitor=new OperationalMonitoringService(store,configuration,new SharedWriteExecutor(new JdbcSharedWriteEntry(source),tx),clock);return new Batch(List.of(new ApiMonitoringCycle(key,facts,store,monitor,clock)),facts);
 }
 @Bean(destroyMethod="shutdownNow") @ConditionalOnMissingBean(name="apiMonitoringExecutor") ScheduledExecutorService apiMonitoringExecutor(){var executor=new ScheduledThreadPoolExecutor(1,task->{var thread=new Thread(task,"api-monitor");thread.setDaemon(true);return thread;});executor.setRemoveOnCancelPolicy(true);executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);executor.setContinueExistingPeriodicTasksAfterShutdownPolicy(false);return executor;}
 @Bean Loop apiMonitoringLoop(Batch batch,@Qualifier("apiMonitoringExecutor")ScheduledExecutorService executor){return new Loop(batch,executor,Clock.systemUTC());}
 public static final class Loop implements SmartLifecycle {
  private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(Loop.class);private final Batch batch;private final ScheduledExecutorService executor;private final Clock clock;private boolean running,inFlight;private volatile boolean failure;private ScheduledFuture<?> future;private final List<Runnable> callbacks=new ArrayList<>();
  Loop(Batch batch,ScheduledExecutorService executor,Clock clock){this.batch=Objects.requireNonNull(batch);this.executor=Objects.requireNonNull(executor);this.clock=Objects.requireNonNull(clock);}
  @Override public synchronized void start(){if(running)return;if(inFlight)throw new IllegalStateException("API sampling still stopping");batch.cycles().forEach(ApiMonitoringCycle::start);running=true;Instant now=clock.instant();long delay=Duration.between(now,now.truncatedTo(ChronoUnit.MINUTES).plusSeconds(60)).toNanos();try{future=Objects.requireNonNull(executor.scheduleAtFixedRate(this::tick,delay,TimeUnit.SECONDS.toNanos(60),TimeUnit.NANOSECONDS));}catch(RuntimeException rejected){running=false;batch.cycles().forEach(ApiMonitoringCycle::stop);future=null;throw rejected;}}
  private void tick(){synchronized(this){if(!running||inFlight)return;inFlight=true;}try{boolean failed=false;for(var cycle:batch.cycles()){synchronized(this){if(!running)break;}try{cycle.tick();}catch(RuntimeException unavailable){failed=true;}}if(failed&&!failure)LOG.warn("api_monitoring_sample_failed");failure=failed;}finally{List<Runnable> done;synchronized(this){inFlight=false;done=List.copyOf(callbacks);callbacks.clear();}done.forEach(Runnable::run);}}
  @Override public void stop(){stop(null);}@Override public void stop(Runnable callback){boolean done;synchronized(this){running=false;batch.cycles().forEach(ApiMonitoringCycle::stop);if(future!=null){future.cancel(true);future=null;}done=!inFlight;if(!done&&callback!=null)callbacks.add(callback);}if(done&&callback!=null)callback.run();}
  @Override public synchronized boolean isRunning(){return running;}@Override public int getPhase(){return Integer.MAX_VALUE;}public boolean hasFailure(){return failure;}
 }
}
